syntax:
for (int pass = 0; pass < N - 1; pass++) {        // N - 1 passes
    for (int j = 0; j < N - 1 - pass; j++) {      // inner loop shrinks every pass
        if (a[j] > a[j + 1]) {                    // use < for descending order
            int temp = a[j];                      // swap with a temporary box
            a[j] = a[j + 1];
            a[j + 1] = temp;
        }
    }
}
// optional early exit:
//   bool swapped = false;  at the start of each pass
//   swapped = true;        inside the if, after a swap
//   if (!swapped) break;   after the inner loop

sample.code:
#include <iostream>
using namespace std;

int main() {
    const int N = 5;
    int a[N] = {5, 1, 4, 2, 8};

    for (int pass = 0; pass < N - 1; pass++) {
        for (int j = 0; j < N - 1 - pass; j++) {
            if (a[j] > a[j + 1]) {
                int temp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = temp;
            }
        }
        cout << "After pass " << pass + 1 << ": ";
        for (int k = 0; k < N; k++) {
            cout << a[k] << " ";
        }
        cout << endl;
    }

    cout << "Sorted: ";
    for (int k = 0; k < N; k++) {
        cout << a[k] << " ";
    }
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    const int N = 5;
    int a[N] = {1, 2, 4, 3, 5};
    int comparisons = 0;
    int passes = 0;

    for (int pass = 0; pass < N - 1; pass++) {
        bool swapped = false;
        passes++;
        for (int j = 0; j < N - 1 - pass; j++) {
            comparisons++;
            if (a[j] > a[j + 1]) {
                int temp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = temp;
                swapped = true;
            }
        }
        cout << "After pass " << pass + 1 << ": ";
        for (int k = 0; k < N; k++) {
            cout << a[k] << " ";
        }
        cout << endl;
        if (!swapped) {
            break;
        }
    }

    cout << "Passes used: " << passes << endl;
    cout << "Comparisons: " << comparisons << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    const int N = 4;
    int a[N] = {7, 3, 5, 1};
    int comparisons = 0;
    int swaps = 0;

    for (int j = 0; j < N - 1; j++) {
        comparisons++;
        if (a[j] > a[j + 1]) {
            int temp = a[j];
            a[j] = a[j + 1];
            a[j + 1] = temp;
            swaps++;
        }
    }

    cout << "After pass 1: ";
    for (int k = 0; k < N; k++) {
        cout << a[k] << " ";
    }
    cout << endl;
    cout << "Comparisons: " << comparisons << endl;
    cout << "Swaps: " << swaps << endl;
    return 0;
}

